const executableName = process.platform === "win32" ? "oxlint.exe" : "oxlint";

const packageRoot = findPackageRoot(fileURLToPath(import.meta.url));

export const resolveOxlintEffectPath = (): string => {
  const candidates = [
    process.env.TIARA_OXLINT_EFFECT_PATH,
    process.env.TIARA_REAL_OXLINT_PATH,
    join(packageRoot, "vendor", `${process.platform}-${process.arch}`, executableName),
    findUp(
      process.cwd(),
      join("native", "oxc-oxlint-effect-fork", "target", "release", executableName),
    ),
    findUp(
      packageRoot,
      join("native", "oxc-oxlint-effect-fork", "target", "release", executableName),
    ),
  ].filter((path): path is string => Boolean(path));

  const binaryPath = candidates.find((path) => existsSync(path));
  if (!binaryPath) {
    throw new Error(
      [
        "Unable to locate oxlint-effect.",
        "Build native/oxc-oxlint-effect-fork/target/release/oxlint or install a platform package that provides vendor binaries.",
        "Set TIARA_OXLINT_EFFECT_PATH to override the binary path.",
      ].join(" "),
    );
  }

  return binaryPath;
};

function findPackageRoot(start: string): string {
  let directory = dirname(start);
  while (true) {
    if (existsSync(join(directory, "package.json"))) {
      return directory;
    }
    const parent = dirname(directory);
    if (parent === directory) {
      return resolve(".");
    }
    directory = parent;
  }
}

function findUp(start: string, relativePath: string): string | undefined {
  let directory = resolve(start);
  while (true) {
    const candidate = join(directory, relativePath);
    if (existsSync(candidate)) {
      return candidate;
    }
    const parent = dirname(directory);
    if (parent === directory) {
      return undefined;
    }
    directory = parent;
  }
}

/**
 * Oxlint tool resolver for the vite-plus CLI.
 *
 * This module exports a function that resolves the oxlint binary path
 * using Node.js module resolution. The resolved path is passed back
 * to the Rust core, which then executes oxlint for code linting.
 *
 * Used for: `vite-plus lint` command
 *
 * Oxlint is a fast JavaScript/TypeScript linter written in Rust that
 * provides ESLint-compatible linting with significantly better performance.
 */

import { existsSync } from 'node:fs';
import { dirname, join } from 'node:path';

import { CONFIG_METADATA_ENV, DEFAULT_ENVS, resolve } from './utils/constants.ts';
import { resolveTsgolintExecutable } from './utils/tsgolint-path.ts';

export { resolveWindowsTsgolintExecutable } from './utils/tsgolint-path.ts';

/**
 * Resolves the oxlint binary path and environment variables.
 *
 * @returns Promise containing:
 *   - binPath: Absolute path to the oxlint binary
 *   - envs: Environment variables to set when executing oxlint
 *
 * The environment variables provide runtime context to oxlint,
 * including Node.js version information and package manager details.
 */
export async function lint(): Promise<{
  binPath: string;
  envs: Record<string, string>;
}> {
  // Resolve the oxlint package path first, then navigate to the bin file.
  // The bin/oxlint subpath is not exported in package.json exports, so we
  // resolve the main entry point and derive the bin path from it.
  // resolve('oxlint') returns .../oxlint/dist/index.js, so we need to go up
  // two directories (past 'dist') to reach the package root.
  const oxlintMainPath = resolve('oxlint');
  const oxlintPackageRoot = dirname(dirname(oxlintMainPath));
  const binPath = join(oxlintPackageRoot, 'bin', 'oxlint');
  const upstreamTsgolintPath = resolveTsgolintExecutable(
    resolve('oxlint-tsgolint/bin/tsgolint'),
    import.meta.url,
  );
  const oxlintTsgolintPath = resolveTiaraTsgolintExecutable() ?? upstreamTsgolintPath;
  const result = {
    binPath,
    // TODO: provide envs inference API
    envs: {
      ...DEFAULT_ENVS,
      OXLINT_TSGOLINT_PATH: oxlintTsgolintPath,
      // oxlint loads vite.config.ts only to read the `lint` block, so skip the
      // user's Vite plugin factory (lazyPlugins) while it evaluates the config.
      [CONFIG_METADATA_ENV]: '1',
    },
  };
  return result;
}

function resolveTiaraTsgolintExecutable(): string | undefined {
  const candidate =
    process.env.TIARA_TSGOLINT_EFFECT_PATH ??
    resolveOptional('@tiara-stack/tsgolint-effect/bin/tsgolint-effect');
  return candidate && existsSync(candidate) ? candidate : undefined;
}

function resolveOptional(path: string): string | undefined {
  try {
    return resolve(path);
  } catch {
    return undefined;
  }
}
